/// <summary>
/// CB788_CustomPricingComponents
/// </summary>
public class METComponentCodeDetail extends common
{
}

Method.Source:
/// <summary>
/// Method to retrieve the component code detail or component code main account
/// </summary>
/// <param name = "_component">The <c>METComponent</c> value to retrieve the component code detail record.</param>
/// <param name = "_code">The <c>METComponentCodeId</c> value to retrieve the component code detail record.</param>
/// <returns>Main account from component code detail or component code</returns>
static MainAccountNum getMainAccountId(METComponent _component, METComponentCodeId _code)
{
    METComponentCodeDetail  componentCodeDetail = METComponentCodeDetail::find(_component, _code);
    if (componentCodeDetail.MainAccountId)
    {
        return componentCodeDetail.MainAccountId;
    }
    else
    {
        return METComponentCode::findComponent(_component).MainAccountId;
    }
}

    /// <summary>
    /// Find a component code detail record using component
    /// </summary>
    /// <param name = "_component">The <c>METComponent</c> value to retrieve the component code detail record.</param>
    /// <param name = "_code">The <c>METComponentCodeId</c> value to retrieve the component code detail record.</param>
    /// <param name = "_forUpdate">Specifies if record is selected for update</param>
    /// <param name = "_concurrencyModel">Specifies concurrency model</param>
    /// <returns>Found component code detail record; otherwise, blank.</returns>
    static METComponentCodeDetail find(METComponent         _component, 
                                       METComponentCodeId   _code,
                                       boolean              _forUpdate = false,
                                       ConcurrencyModel     _concurrencyModel = ConcurrencyModel::Auto)
    {
        METComponentCodeDetail  componentCodeDetail;

        if (_component && _code)
        {
            if (_forUpdate)
            {
                componentCodeDetail.selectForUpdate (_forUpdate);
                if (_concurrencyModel != ConcurrencyModel::Auto)
                {
                    componentCodeDetail.concurrencyModel(_concurrencyModel);
                }
            }
            componentCodeDetail.selectLocked(_forUpdate);

            select firstonly componentCodeDetail
                       where componentCodeDetail.Component == _component
                          && componentCodeDetail.Code      == _code;
        }

        return componentCodeDetail;
    }
